// Wybor backendu: 'shopify' (domyslny) lub 'baselinker'.
const backend = ($json.backend || 'shopify').toLowerCase();
const orderId = ($json.order_id || '').replace(/[^0-9]/g, '');
if (!orderId) {
  return [{ json: { error: 'invalid_order_id', order_id: $json.order_id } }];
}
return [{ json: { backend, order_id: orderId } }];

const o = $json.order;
if (!o) return [{ json: { error: 'order_not_found' } }];
return [{ json: {
  order_id: String(o.id),
  status: o.financial_status,
  fulfillment_status: o.fulfillment_status,
  total_price: parseFloat(o.total_price),
  currency: o.currency,
  line_items_count: (o.line_items || []).length,
  customer: {
    name: `${o.customer?.first_name || ''} ${o.customer?.last_name || ''}`.trim(),
    email: o.customer?.email
  },
  shipping: {
    method: o.shipping_lines?.[0]?.title,
    address: o.shipping_address ? `${o.shipping_address.address1}, ${o.shipping_address.zip} ${o.shipping_address.city}` : null
  },
  tracking: {
    number: o.fulfillments?.[0]?.tracking_number || null,
    carrier: o.fulfillments?.[0]?.tracking_company || null
  },
  created_at: o.created_at
}}];

const o = $json.orders?.[0];
if (!o) return [{ json: { error: 'order_not_found' } }];
return [{ json: {
  order_id: String(o.order_id),
  status: o.order_status_id,
  total_price: parseFloat(o.price_brutto),
  currency: o.currency,
  line_items_count: (o.products || []).length,
  customer: {
    name: `${o.delivery_fullname || ''}`.trim(),
    email: o.email
  },
  shipping: {
    method: o.delivery_method,
    address: `${o.delivery_address}, ${o.delivery_postcode} ${o.delivery_city}`
  },
  tracking: {
    number: o.delivery_package_nr || null,
    carrier: o.delivery_package_module || null
  },
  created_at: new Date(o.date_add * 1000).toISOString()
}}];
